import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.uw_ZoRon.js";const u=JSON.parse('{"title":"Byte streams","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/byte-streams.md","filePath":"deep-dive/byte-streams.md"}'),s={name:"deep-dive/byte-streams.md"};function n(d,e,c,i,h,l){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="byte-streams" tabindex="-1">Byte streams <a class="header-anchor" href="#byte-streams" aria-label="Permalink to &quot;Byte streams&quot;">​</a></h1><p>Messages are whole values: you <code>send</code> a chunk, the receiver gets that chunk. But some work is a <em>flow</em> — an HTTP body, an SSE feed, a file being piped — where the producer keeps emitting and the consumer keeps reading, and neither should buffer the whole thing in memory. RUSM models that as a <strong>byte stream</strong> between processes: a bounded, back-pressured channel whose read end is handed off like any other message.</p><h2 id="when-you-actually-use-it" tabindex="-1">When you actually use it <a class="header-anchor" href="#when-you-actually-use-it" aria-label="Permalink to &quot;When you actually use it&quot;">​</a></h2><p>A byte stream is a <strong>low-level primitive</strong>. Its heaviest user is RUSM&#39;s own <strong>serving layer</strong>: an SSE or streaming HTTP/WS body rides a back-pressured byte stream, so a slow client throttles the producer instead of forcing the server to buffer a whole response — and you get that for free by writing a normal SSE/WS handler, never touching the stream API. An <strong>application component</strong> reaches for the raw producer/consumer API directly only to pipe a large or open-ended payload from one component to <em>another</em> — a proxy forwarding an upload, a transcoding stage, an LLM-token relay. For everything else, component-to-component talks in messages (<code>send</code>/<code>receive</code>) and client streaming goes through the serving API.</p><h2 id="a-bounded-channel-the-actor-way" tabindex="-1">A bounded channel, the actor way <a class="header-anchor" href="#a-bounded-channel-the-actor-way" aria-label="Permalink to &quot;A bounded channel, the actor way&quot;">​</a></h2><p>A stream is a <strong>bounded Tokio channel</strong> of byte chunks (<code>StreamHandle</code> in the Wasm-free <code>rusm-otp</code> core). The read end travels in a message — <code>Received::Stream</code> — moving ownership to the recipient exactly like any other message. So streams are pure actor composition: no shared memory, no new wiring.</p><h2 id="back-pressure-for-free" tabindex="-1">Back-pressure for free <a class="header-anchor" href="#back-pressure-for-free" aria-label="Permalink to &quot;Back-pressure for free&quot;">​</a></h2><p>Because the channel is bounded, a slow reader automatically slows the writer: the writer&#39;s <code>stream_write</code> simply <strong>parks its fiber</strong> until there&#39;s room (see <a href="/rusm/deep-dive/fibers-and-blocking-to-async">fibers &amp; blocking→async</a>). No busy-polling, no unbounded memory growth — the safety property that lets a component stream an HTTP/SSE/WS body without falling over.</p><h2 id="from-guests" tabindex="-1">From guests <a class="header-anchor" href="#from-guests" aria-label="Permalink to &quot;From guests&quot;">​</a></h2><p>A Wasm guest drives streams through the actor ABI — both <strong>components</strong> (the <code>rusm:runtime</code> WIT world: <code>stream-open</code>/<code>write</code>/<code>close</code>/<code>accept</code>/<code>read</code>) and <strong>wasip1 core modules</strong> (the raw <code>rusm::*</code> ABI). <code>stream-open(to)</code> hands the read end to another process and keeps the write end; the write/read ops move chunks. The two byte copies — <em>out of</em> the producer&#39;s sandboxed memory and <em>into</em> the consumer&#39;s — are the price of true isolation; everything between is a zero-copy channel hand-off. The <strong>stream-pipe</strong> benchmark sustains multiple GB/s across producer→consumer pairs.</p><blockquote><p>Shipped in Phase 7 (core <code>StreamHandle</code> in Phase 2; the guest ABI in Phase 7).</p></blockquote>',11)])])}const p=o(s,[["render",n]]);export{u as __pageData,p as default};
